#!/usr/bin/env python3
"""Reproduce UART IRQ/packet and pre-sleep input evidence from original bytes/RAM."""
from pathlib import Path
import hashlib,json,mmap,struct
import capstone
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];BASE=0x6280000
src=ROOT/'s5-v29-offline/unpacked-v29/03_program.bin';p=src.read_bytes();sha=hashlib.sha256(p).hexdigest()
assert sha=='fc496d62a91f6e9b1b84807183bb805bc546c9105d2938546b58a66ad9d132fe'
folder=ROOT/'s5-emulator/menu-smp/results/pre-sleep-checkpoint';boot=json.loads((folder/'result.json').read_text())
with (folder/'ram.bin').open('rb')as f:
 r=mmap.mmap(f.fileno(),0,access=mmap.ACCESS_READ);u32=lambda a:struct.unpack_from('<I',r,a)[0];u16=lambda a:struct.unpack_from('<H',r,a)[0]
 rows=[]
 for channel in range(5):
  mmio_source=0x70d5130+4*channel;logical_source=0x70d5144+4*channel
  mmio=struct.unpack_from('<I',p,mmio_source-BASE)[0];logical=struct.unpack_from('<I',p,logical_source-BASE)[0]
  mapped=struct.unpack_from('<I',p,0x6ff1240-BASE+logical*4)[0]
  assert mmio==u32(0x8ab4778+4*channel) and logical==u32(0x8ab478c+4*channel)
  rows.append({'channel':channel,'mmio':hex(mmio),'mmio_source':hex(mmio_source),'logical_irq':hex(logical),'logical_irq_source':hex(logical_source),'gic_mapping_entry':hex(0x6ff1240+logical*4),'gic_id':mapped,'spi_input':mapped-32})
 def packet(a):
  txptr=u32(a+4) or a+0x10;return {'address':hex(a),'tx_len':u16(a),'tx_pointer':hex(txptr),'tx_hex':r[txptr:txptr+u16(a)].hex(),'rx_len':u16(a+8),'rx_pointer':hex(u32(a+12) or a+0x18)}
 uart={'original_firmware':str(src),'sha256':sha,'source_of_runtime_evidence':str(folder/'result.json'),'channels':rows,'rx_drain':{'entry':'0x0648f2cc','loop':'0x0648f34e..0x0648f358','status':'FR+0x18 bit4=RXFE','behavior':'Read/discard DR while RXFE=0. Unmodeled FR=0 falsely reports endless RX data.','after_drain':'Enable CR RXE bit9, IMSC|=0x7d0, UARTEN bit0'},'setup_observed_before_mapping':{'IBRD':7,'FBRD':21,'LCRH':'0x76','IFLS':'0x12','character_format':'8 data bits, even parity, 1 stop bit, FIFO enabled','physical_clock_baud_not_verified':True},'packets':[packet(0x8ab12d0),packet(0x8ab13d0)],'actual_uart_transmissions':boot['uart_transmissions'],'reply_parse':{'function':'0x06448bc8','0x34':'Requires 5 bytes with byte0=0x34; stores (byte2<<8)|byte4 at 0x08c9a198+0x20c and byte1 at 0x062a9000+0x288','0x27':'Requires 4 bytes with byte0=0x27; stores (byte1<<12)+(byte2<<8)+byte3 at 0x08c9a198+0x20a','field_physical_meanings':'Unproven; do not fabricate successful replies from these checks.'},'timeout':{'wrapper':'0x064497fe','implementation':'0x06448a6a','timer_accessor':'0x067076d4(1) -> 0x06554d72(1)','ordinary_ticks':675000,'special_command':hex(r[0x8ab14c0]),'special_ticks':33750000,'seconds_at_1687500Hz':{'ordinary':0.4,'special':20},'timeout_returns':3,'wrapper_loops_only_on_return':1},'endpoint_identity':{'verified':False,'candidate_component':'32_usbcharge.bin has USBCHARGE header and Cortex-M vectors, but protocol association was not established. Not used to generate responses.'},'limits':['PL011 transport modeled; no external UART peer or reply was simulated.','SPI0 prior progress used explicitly absent-peer MISO0; uploading bytes is not coprocessor completion.','No menu rendering proved by these results.']}
 regs=boot['final_registers'][0];sp=int(regs['r13'],16);table=u32(0x8a9db28)
 power={'original_firmware':str(src),'sha256':sha,'checkpoint':str(folder/'result.json'),'registers':regs,'checkpoint_pc_expected':'0x0653efe2','sample_stack_address':hex(sp),'sample':u16(sp),'source_reads':[{'api_channel':8,'mmio':hex(u32(0x8aa7dec+8*4)),'role':'First sample, possibly offset-corrected'},{'api_channel':11,'mmio':hex(u32(0x8aa7dec+11*4)),'role':'Second sample; main selects maximum'}],'adc_table_ram':'0x08aa7dec','threshold_table_pointer':hex(table),'thresholds':{'r9_offset_0x12':u16(table+0x12),'r10_offset_0x0e':u16(table+0x0e),'final_offset_0x1c':u16(table+0x1c)},'state_flags':{'0x062b5c18':u16(0x62b5c18),'0x062b5c1a':u16(0x62b5c1a),'0x08ab1209':r[0x8ab1209]},'actual_path':['main 0x063c8a7a calls 0x0653ee1c regardless of UART return value','0x0653efb8 compares sample0 against0x26d; below','0x0653efc0 calls0x0653edb4, which sets backup register0x0424 bit3','0x0653efcc compares threshold0x25e againstsample0; thresholdgreater','0x0653efe2 about to call0x0644f9be DRAM sleep path'],'explicit_environment_proposal':{'adc11_raw':0x300,'scope':'Input sample only; no firmware branch, task event, threshold, or successful UART reply patch.','expected_original_branch':'0x0653efbe BHS0x0653ef84 avoids this low-sample sleep path','physical_voltage_conversion':'Unknown; raw768 is an explicit experimental environment value, not a measured camera voltage.'},'independent_sram_failure':{'evidence':'menu-smp/results/uart-controllers-boot/qemu/qemu-trace.log','initial_mapping':'Only0x70028000..0x70028fff had RAM backing','original_stack':'0x7002a3f0 set by0x068e8040','ignored_saved_return_addresses':{'0x7002a3d4':'0x7002804f','0x7002a3c4':'0x70028315','0x7002a3b4':'0x70028205'},'inference':'Original sleep SPI routine POP read dropped stack aszero, leading toPC0/loader reset loop. This reset artifact is separate from the intentional entry into sleep.','minimum_observed_extent':'Must cover at least0x70028000..0x7002a3ff for code and stack.'},'supply_check_physical_name':'ADC/threshold behavior verified; exact board electrical input and volts not verified.'}
 (HERE/'uart-evidence.json').write_text(json.dumps(uart,indent=2)+'\n');(HERE/'power-sleep-evidence.json').write_text(json.dumps(power,indent=2)+'\n')
lines=[f'03_program.bin sha256={sha}; addresses are firmware VA, Thumb.']
for a,n in [(0x648f1e8,0x60),(0x648f2cc,0xbc),(0x648f576,0x92),(0x6448a32,0x140),(0x6448bc8,0x5a),(0x6449314,0x96),(0x64497fe,0x1a),(0x653edb4,0x234),(0x659ed98,0x174),(0x67076d4,0x10),(0x644faa2,0x1c)]:
 lines.append('\nRANGE '+hex(a));md=capstone.Cs(capstone.CS_ARCH_ARM,16);md.skipdata=True
 for i in md.disasm(p[a-BASE:a-BASE+n],a):lines.append(f'{i.address:08x}: {i.bytes.hex():10} {i.mnemonic:9} {i.op_str}')
(HERE/'uart-power.disasm.txt').write_text('\n'.join(lines)+'\n')
print('Wrote uart-evidence.json, power-sleep-evidence.json, uart-power.disasm.txt')
